class Incident(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    id: Id
    fault_ref: Id
    start: Timestamp
    onset_minutes: confloat(ge=0.0, le=1440.0) | None = None
    peak_minutes: confloat(le=1440.0, gt=0.0) | None = None
    recovery_minutes: confloat(ge=0.0, le=1440.0) | None = None
    peak_rate: Rate | None = None
    baseline_rate: Rate | None = Field(
        None,
        description='Share of eligible sessions affected outside the incident; onset rises from it to peak_rate and recovery returns to it. Defaults to 0.',
    )
    curve: Curve | None = Field(
        None,
        description='Onset and recovery easing. smooth uses a raised cosine, so a short peak gives a bell-shaped rise and fall. Defaults to linear.',
    )
    repeat_every_minutes: confloat(ge=2.0, le=10080.0) | None = None


class Kind2(Enum):
    app_version = 'app_version'
    web_release = 'web_release'
    service_version = 'service_version'
    feature_cohort = 'feature_cohort'


class Rollout(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    id: Id
    kind: Kind2
    subject: constr(min_length=1, max_length=128)
    canary_share: confloat(ge=0.0, le=0.999) | None = None
    start: Timestamp | None = None
    rollback_at: Timestamp | None = None
    cohort_seed: constr(pattern=r'^[a-z0-9][a-z0-9-]{0,62}$') | None = None


class IncidentPhase(Enum):
    onset = 'onset'
    incident = 'incident'
    recovery = 'recovery'


class PrimaryScenario(Enum):
    clean = 'clean'
    mobile = 'mobile'
    backend = 'backend'
    slow = 'slow'
    handled = 'handled'
    blockage = 'blockage'
    crash = 'crash'


class BlockageCause(Enum):
    migration = 'migration'
    worker_lock = 'worker_lock'
    layout = 'layout'


class RolloutPhase(Enum):
    active = 'active'
    rollback = 'rollback'


class VerificationCase(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    name: constr(pattern=r'^[a-z0-9][a-z0-9/_-]{0,127}$')
    line_of_business: LineOfBusiness
    target: Id | None = None
    backend_fault: constr(pattern=r'^[a-z0-9][a-z0-9-]{0,62}$') | None = None
    incident_phase: IncidentPhase | None = None
    primary_scenario: PrimaryScenario | None = None
    crash_family: conint(ge=0, le=4) | None = None
    blockage_cause: BlockageCause | None = None
    full_journey: bool | None = Field(
        None,
        description='Run the complete priority flow (checkout, transfer, booking).',
    )
    rollout_phase: RolloutPhase | None = None


class IosTarget(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    sdk_version: constr(pattern=r'^[0-9]+\.[0-9]+\.[0-9]+$') | None = None
    versions: list[Version] | None = Field(None, max_length=12, min_length=1)
    bundle_id: constr(pattern=r'^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$') | None = None


class Causal(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    scenario: Scenario
    variant: Variant | None = None
    mode: Mode | None = None
    cache: Cache | None = None
    network: Network1 | None = None
    reference: bool | None = None
    result_count: conint(ge=1, le=100) | None = None
    client_failure: ClientFailure | None = None
    connectivity_phase: ConnectivityPhase | None = None
    retry: bool | None = None
    partial_results: bool | None = None
    region: Region | None = None
    service_release: constr(pattern=r'^[0-9]{4}\.[0-9]{2}\.[0-9]{1,2}$') | None = None
    incident_start: Timestamp | None = None
    incident_minutes: confloat(ge=1.0, le=120.0) | None = None
    cohort_share: Share | None = None
    mix: Mix | None = None
    replay_namespace: constr(pattern=r'^[a-f0-9]{32}$') | None = Field(
        None, description='Exact-ID diagnostic replay. Local dry runs only.'
    )
    web_widget: bool | None = Field(
        None,
        description='Web-only blocking interaction variant, exclusive with the view-state failure.',
    )
    provider: Provider | None = Field(
        None,
        description='One consented external client request; no invented provider SERVER spans.',
    )
    version: Literal['1.0.0'] | None = Field(
        None, description='Causal execution model version.'
    )


class Estate(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    retail: Site | None = None
    banking: Site | None = None
    travel: Site | None = None


class WebTarget(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    sdk_version: constr(pattern=r'^[0-9]+\.[0-9]+\.[0-9]+$') | None = None
    estate: Estate | None = None
    cdn: Origin | None = None
    releases: list[Release1] | None = Field(None, max_length=12)
    router_integration: RouterIntegration | None = None
    sdk_upload_spans: bool | None = Field(
        None,
        description="Whether the SDK's own uploads to a-<appId>.data.emb-api.com appear as network spans (SDK default: true).",
    )
    origin_header: OriginHeader | None = None
    propagation_allow_list: list[Hostname] | None = None
    symbolication: bool | None = Field(
        False,
        description='Emit bundle IDs for executable release assets. Upload all maps with explicit confirmation before live exceptions.',
    )


class Target(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    id: Id
    platform: Platform1
    embrace_app_id: constr(pattern=r'^[A-Za-z0-9]{5}$')
    app_name: constr(min_length=1, max_length=64) | None = Field(
        None,
        description='Name of the app in Embrace; forwarded client spans use lower(name with spaces as underscores)-<platform>-<environment> as service.name.',
    )
    environment: Environment | None = None
    region: Region1 | None = None
    api_domains: ApiDomains | None = None
    otlp_endpoint: constr(max_length=512) | None = None
    android: AndroidTarget | None = None
    web: WebTarget | None = None
    ios: IosTarget | None = None


class ScenarioSpec(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    modeling: Modeling | None = None
    spec_version: Literal['2.0'] = Field(
        ..., description='Schema version of this document.'
    )
    name: constr(max_length=120) | None = None
    causal: Causal | None = None
    seed: int | None = Field(
        None,
        description='Seed for reproducible output; null draws a fresh seed per run.',
    )
    notes: constr(max_length=4000) | None = Field(
        None, description='Operator notes. Never emitted.'
    )
    stories: list[Id] | None = Field(
        None,
        description='Preset identifiers applied to this document, recorded for provenance. Never emitted.',
    )
    targets: list[Target] = Field(..., max_length=8, min_length=1)
    chronosphere: Chronosphere | None = None
    destinations: Destinations
    population: Population | None = None
    traffic: Traffic
    client_faults: list[ClientFault] | None = Field(None, max_length=64)
    web_performance: list[WebPerformance] | None = Field(None, max_length=64)
    backend_faults: list[BackendFault] | None = Field(None, max_length=64)
    incidents: list[Incident] | None = Field(None, max_length=64)
    rollouts: list[Rollout] | None = Field(None, max_length=32)
    verification_cases: list[VerificationCase] | None = Field(
        None,
        description='Bounded cases generated first; the normal distribution resumes afterwards. Excluded from population-rate claims.',
        max_length=200,
    )
